const IH_TIDE_SOURCE='Instituto Hidrográfico · Tabela de Marés 2026 · Sines';
const IH_TIDE_URL='https://loja.hidrografico.pt/ln/web/wp-content/uploads/2023/11/TabelaMare_I_2026_signed.pdf';
const TIDE_EVENTS=Object.entries(IH_TIDES_SINES_2026_11).flatMap(([day,rows])=>rows.map(([hm,height],idx)=>({
 date:'2026-11-'+day,clock:hm,iso:'2026-11-'+day+'T'+hm+':00Z',height,kind:height>=2?'high':'low',epoch:Date.parse('2026-11-'+day+'T'+hm+':00Z')
}))).sort((a,b)=>a.epoch-b.epoch);
function tideAt(date,period,window){
 if(!String(date).startsWith('2026-11-'))return null;
 const m=String(window||'').match(/(\d{2}):(\d{2})\s*[–-]\s*(\d{2}):(\d{2})/);
 const start=m?(+m[1]*60 + +m[2]):{Madrugada:0,Amanhecer:360,Manhã:510,Tarde:720,Anoitecer:990,Noite:1110}[period]??720;
 const end=m?(+m[3]*60 + +m[4]):start+120;
 const mid=(start+end)/2, epoch=Date.parse(date+'T00:00:00Z')+mid*60000;
 const lows=TIDE_EVENTS.filter(x=>x.kind==='low'), low=lows.slice().sort((a,b)=>Math.abs(a.epoch-epoch)-Math.abs(b.epoch-epoch))[0];
 if(!low||Math.abs(low.epoch-epoch)>26*3600000)return null;
 const idx=TIDE_EVENTS.indexOf(low);const after=TIDE_EVENTS.slice(idx+1).find(x=>x.kind==='high');const before=TIDE_EVENTS.slice(0,idx).reverse().find(x=>x.kind==='high');
 const pair=after||before,range=pair?Math.max(0,+(pair.height-low.height).toFixed(2)):null;
 const nearby=TIDE_EVENTS.slice().sort((a,b)=>Math.abs(a.epoch-epoch)-Math.abs(b.epoch-epoch))[0];
 const last=TIDE_EVENTS.filter(x=>x.epoch<=epoch).at(-1);const next=TIDE_EVENTS.find(x=>x.epoch>epoch);
 let phase='maré em evolução';
 if(nearby&&Math.abs(nearby.epoch-epoch)<=70*60000)phase=nearby.kind==='low'?'perto da baixa-mar':'perto da preia-mar';
 else if(last&&next)phase=last.kind==='low'?'enchente':'vazante';
 const lowMin=(low.epoch-Date.parse(date+'T00:00:00Z'))/60000;
 const ordinal=+date.slice(8,10), sunrise=7*60+Math.round(3+(ordinal-3)*1.05),sunset=17*60+Math.round(35-(ordinal-3)*.65);
 const dayOverlap=Math.max(0,Math.min(end,lowMin+90,sunset)-Math.max(start,lowMin-90,sunrise));
 return {lowDate:low.date,lowTime:low.clock,lowHeight:low.height,range,highTime:pair?.clock||null,phase,distMinutes:Math.round(Math.abs(lowMin-mid)),windowOverlapMinutes:Math.round(dayOverlap),sunriseMinutes:sunrise,sunsetMinutes:sunset,reference:'IH_Sines_2026_ZH_TU0',source:IH_TIDE_SOURCE};
}
function addSamoqueiraProxy(data){
 if(!data.beaches.samoqueira)data.beaches.samoqueira={name:'Samoqueira',lat:37.86728,lon:-8.79315,profile:'Enseada com rocha, pequenas zonas arenosas e canais; acessos exigentes',depth:'Areia e pedra; desníveis e canais locais por confirmar',bottom:'Rocha e areia',structure:8.8,exposure:6.8,best_for:['Robalo','Sargo'],where:'Procurar transições e canais apenas de locais seguros; evitar zonas expostas nas rochas.',ideal:'Mar pequeno e águas limpas; acessos, visibilidade e permissões a verificar.',avoid:'Rebentação nas pedras, escorregamentos e engates na pesca de fundo.',rig:'Surfcasting excluído por preferência do utilizador.'};
 const existing=new Set(data.evaluations.filter(e=>e.beach_id==='samoqueira').map(e=>e.date+'|'+e.period+'|'+e.species));
 for(const base of data.evaluations.filter(e=>e.beach_id==='porto-covo')){
   const k=base.date+'|'+base.period+'|'+base.species;if(existing.has(k))continue;
   const e=structuredClone(base);e.beach_id='samoqueira';e.confidence=Math.min(43,e.confidence||43);
   e.conditions.effective_wave_m=+(Number(base.conditions?.wave_offshore_m||0)*.76).toFixed(2);
   e.conditions.data_origin_level='regional ajustado (proxy Porto Covo)';
   e.conditions.primary_source='Proxy regional Porto Covo · NÃO é medição em Samoqueira';
   e.conditions.source_note='Sem previsão específica da enseada. Apenas cenário meteorológico para atividades não surfcasting.';
   e.summary='Samoqueira: condições regionais aproximadas a partir de Porto Covo; surfcasting excluído por preferência. Sem observação do fundo nem visibilidade.';
   e.why_not_10='A praia tem rochas e acessos exigentes; previsão regional extrapolada. Não usar este índice de surfcasting.';
   data.evaluations.push(e);
 }
}
function enrichForecast(data){
 addSamoqueiraProxy(data);
 if(data.tide_enrichment_version==='IH_Sines_2026_11_v1')return data;
 for(const e of data.evaluations){
   const t=tideAt(e.date,e.period,e.window);if(!t)continue;
   const c=e.conditions||(e.conditions={});
   Object.assign(c,{tide_phase:t.phase,tide_low_height_m:t.lowHeight,tide_range_m:t.range,tide_low_time:t.lowTime,tide_low_date:t.lowDate,tide_high_time:t.highTime,tide_low_distance_min:t.distMinutes,tide_daylight_overlap_min:t.windowOverlapMinutes,tide_reference:t.reference,tide_source:IH_TIDE_URL});
   if(e.beach_id==='samoqueira')continue;
   const f=e.factors?.find(f=>f.id==='mare');if(!f)continue;
   const oldImpact=Number(f.impact)||0;
   const phaseScore=t.phase==='enchente'?8.7:t.phase==='perto da preia-mar'?8.0:t.phase==='perto da baixa-mar'?7.0:6.6;
   const rangeScore=clamp(5.5+((t.range??1.5)-1.5)*2,0,10);
   f.score=+clamp(phaseScore*.82+rangeScore*.18).toFixed(2);f.impact=+(f.score*f.weight).toFixed(2);
   f.value=t.phase+'; amplitude '+(t.range?.toFixed(1)||'—')+' m';f.unit='';
   f.reason='Fase calculada a partir dos extremos oficiais de Sines. Baixa-mar '+t.lowDate+' às '+t.lowTime+' ('+t.lowHeight.toFixed(1)+' m, zero hidrográfico); amplitude para preia-mar adjacente '+(t.range?.toFixed(1)||'—')+' m. A mesma amplitude afeta correntes e alimento de forma diferente conforme o tipo de praia. Não é uma maré medida neste areal.';
   f.source=IH_TIDE_SOURCE;f.confidence=.98;
   const original=Number(e.score)||0;
   e.score=+clamp(original+f.impact-oldImpact).toFixed(1);
   if(Number(c.wind_kmh)>=35||Number(c.wave_offshore_m)>=2.7)e.score=Math.min(e.score,4);
 }
 data.tide_enrichment_version='IH_Sines_2026_11_v1';data.tide_source={name:IH_TIDE_SOURCE,url:IH_TIDE_URL,station:'Sines',timezone:'TU+0',vertical_datum:'zero hidrográfico local',note:'Amplitude: preia-mar adjacente posterior menos baixa-mar; fase aplicada a todo o corredor como aproximação regional.'};
 return data;
}

const SURFCASTING_EXCLUDED_BEACH_IDS=new Set(['samoqueira']);
function sanitizeForecast(data){return data}
async function readForecastOverride(){
  const stored=localStorage.getItem(STORAGE_FORECAST);if(!stored)return null;
  if(!stored.startsWith('gz:'))return JSON.parse(stored);
  if(typeof DecompressionStream==='undefined')throw new Error('O navegador não suporta importar a atualização comprimida.');
  const bytes=Uint8Array.from(atob(stored.slice(3)),x=>x.charCodeAt(0));
  const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
  return await new Response(stream).json();
}
async function writeForecastOverride(data){
  const raw=JSON.stringify(data);
  if(typeof CompressionStream==='undefined'){localStorage.setItem(STORAGE_FORECAST,raw);return;}
  const stream=new Blob([raw]).stream().pipeThrough(new CompressionStream('gzip'));
  const bytes=new Uint8Array(await new Response(stream).arrayBuffer());let binary='';
  for(let i=0;i<bytes.length;i+=16384)binary+=String.fromCharCode(...bytes.subarray(i,i+16384));
  localStorage.setItem(STORAGE_FORECAST,'gz:'+btoa(binary));
}

function sanitizeHistory(rows){return (Array.isArray(rows)?rows:[]).map(h=>({...h,activity:h.activity||'surfcasting'}))}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labelScore=v=>v>=8.5?'Excelente':v>=7.5?'Muito bom':v>=6.5?'Bom':v>=5.5?'Razoável':'Fraco';
function setStatus(msg){$('#status').textContent=msg}
async function loadForecast(){let data=null;try{data=await readForecastOverride()}catch(err){console.warn('Previsão guardada indisponível:',err)}if(!data){const r=await fetch('data/forecast.json',{cache:'no-store'});if(!r.ok)throw new Error('forecast.json indisponível');data=await r.json()}validateForecast(data);data=enrichForecast(sanitizeForecast(data));APP.forecast=data;prepareActivityIndex(data);forecastStatus(data);APP.selection.date=pickForecastDate(data);APP.selection.beach=Object.keys(data.beaches)[0];populateSelectors();syncActivityHistoryFields();renderAll();setStatus('Dados carregados. Abre qualquer nota para ver o raciocínio completo.')}
function validateForecast(d){
 if(!d||d.schema_version!==3||!Array.isArray(d.evaluations)||!d.evaluations.length||!d.beaches||Array.isArray(d.beaches)||typeof d.beaches!=='object')throw new Error('Formato inválido: é necessário forecast.json com schema_version=3, praias e avaliações.');
 if(!d.generated_at||!Number.isFinite(Date.parse(d.generated_at)))throw new Error('O ficheiro não contém uma data de geração válida.');
 for(const e of d.evaluations){
   if(!/^\d{4}-\d{2}-\d{2}$/.test(e.date||'')||!d.beaches[e.beach_id]||!periods.includes(e.period)||!['Geral','Robalo','Sargo','Dourada'].includes(e.species))throw new Error('Previsão incompatível: data, praia, período ou espécie inválidos.');
   if(typeof e.score!=='number'||!Number.isFinite(e.score)||e.score<0||e.score>10||typeof e.confidence!=='number'||e.confidence<0||e.confidence>100||!e.conditions||!Array.isArray(e.factors))throw new Error('Avaliação incompleta ou pontuação fora dos limites.');
   if(e.factors.some(f=>!Number.isFinite(Number(f.weight))||!Number.isFinite(Number(f.score))||Number(f.weight)<0||Number(f.score)<0||Number(f.score)>10))throw new Error('Há fatores inválidos nas justificações.');
 }
 if(d.activity_evaluations!=null){
   if(!Array.isArray(d.activity_evaluations))throw new Error('activity_evaluations tem de ser uma lista.');
   for(const a of d.activity_evaluations){
     if(!/^\d{4}-\d{2}-\d{2}$/.test(a.date||'')||!d.beaches[a.beach_id]||!periods.includes(a.period)||!['surf','spinning','sub','mare'].includes(a.activity))throw new Error('Atividade IA incompatível: data, praia, período ou tipo.');
     if(a.score!=null&&(!Number.isFinite(a.score)||a.score<0||a.score>10)||!Number.isFinite(a.confidence)||a.confidence<0||a.confidence>100||!Array.isArray(a.reasons)||!Array.isArray(a.limits)||!Array.isArray(a.factors))throw new Error('Atividade IA incompleta: nota, confiança ou justificações.');
   }
 }

}
function forecastStatus(data){
 const ds=[...new Set((data.evaluations||[]).map(x=>x.date))].sort();
 const min=ds[0]||'—', max=ds.at(-1)||'—', stamp=Date.parse(data.generated_at);
 const ageHours=(Date.now()-stamp)/3600000, today=localDateISO();
 const old=Number.isFinite(ageHours)&&ageHours>36, out=max<today;
 const msg=out?`Previsão expirada (último dia ${max}). Pede um forecast novo no ChatGPT.`:old?`Previsão com mais de 36 horas (${min} a ${max}). Confirma antes de decidir.`:`Previsão disponível para ${min} a ${max}. Atualizada no ChatGPT em ${new Date(stamp).toLocaleString('pt-PT')}.`;
 const el=$('#manualForecastStatus');if(el){el.textContent=msg;el.classList.toggle('manual-forecast-warning',old||out)}
 $('#dataStamp').textContent=(old||out?'PREVISÃO ANTIGA · ':'Previsão de ')+new Date(stamp).toLocaleDateString('pt-PT');
}
function pickForecastDate(data){const ds=[...new Set(data.evaluations.map(x=>x.date))].sort(),today=localDateISO();return ds.includes(today)?today:(ds.find(x=>x>today)||ds.at(-1))}

function dates(){return [...new Set(APP.forecast.evaluations.map(x=>x.date))].sort()}
