function evaluation(date,bid,period,species){return APP.forecast.evaluations.find(x=>x.date===date&&x.beach_id===bid&&x.period===period&&x.species===species)}
function populateSelectors(){const ds=dates(), bs=beaches();if(!bs.some(([id])=>id===APP.selection.beach))APP.selection.beach=bs[0]?.[0]||null;const fill=(el,items,fn)=>{el.innerHTML='';items.forEach(x=>{const o=document.createElement('option');const [val,text]=fn(x);o.value=val;o.textContent=text;el.appendChild(o)})};fill($('#dateSelect'),ds,x=>[x,new Date(x+'T12:00:00Z').toLocaleDateString('pt-PT',{weekday:'short',day:'2-digit',month:'2-digit',timeZone:'UTC'})]);fill($('#reasonDate'),ds,x=>[x,x]);fill($('#reasonBeach'),bs,x=>[x[0],x[1].name]);fill($('#beachSelect'),bs,x=>[x[0],x[1].name]);fill($('#hBeach'),bs,x=>[x[0],x[1].name]);fill($('#reasonPeriod'),periods,x=>[x,x]);fill($('#hPeriod'),periods,x=>[x,x]);const months=[...new Set(ds.map(x=>x.slice(0,7)))].sort();fill($('#monthSelect'),months,x=>{const [y,m]=x.split('-').map(Number);return [x,new Date(Date.UTC(y,m-1,1)).toLocaleDateString('pt-PT',{month:'long',year:'numeric',timeZone:'UTC'})]});const monthBeach=$('#monthBeachSelect');monthBeach.innerHTML='<option value="ALL">Todas — melhor praia</option>';bs.forEach(([id,b])=>{const o=document.createElement('option');o.value=id;o.textContent=b.name;monthBeach.appendChild(o)});APP.calendar.month=months.includes(APP.calendar.month)?APP.calendar.month:(months[0]||null);if(APP.calendar.beach!=='ALL'&&!bs.some(([id])=>id===APP.calendar.beach))APP.calendar.beach='ALL';$('#dateSelect').value=APP.selection.date;$('#reasonDate').value=APP.selection.date;$('#reasonBeach').value=APP.selection.beach;$('#beachSelect').value=APP.selection.beach;$('#hBeach').value=APP.selection.beach;$('#reasonPeriod').value=APP.selection.period;$('#hPeriod').value=APP.selection.period;$('#hDate').value=APP.selection.date;$('#calendarView').value=APP.calendar.view;$('#monthSelect').value=APP.calendar.month;$('#monthPeriodSelect').value=APP.calendar.period;$('#monthBeachSelect').value=APP.calendar.beach;syncCalendarControls()}
function sortedFor(date,species){return APP.forecast.evaluations.filter(x=>x.date===date&&x.species===species).sort((a,b)=>b.score-a.score)}
function renderSurfDashboard(){const relevant=APP.forecast.evaluations.filter(x=>x.species==='Geral'&&!SURFCASTING_EXCLUDED_BEACH_IDS.has(x.beach_id));const upcoming=relevant.filter(x=>x.date>=localDateISO());const all=(upcoming.length?upcoming:relevant).sort((a,b)=>b.score-a.score);const best=all[0];const b=APP.forecast.beaches[best.beach_id];$('#bestTitle').textContent=`${b.name} · ${best.period}`;$('#bestScore').textContent=`${best.score.toFixed(1)}/10 · ${labelScore(best.score)}`;$('#bestConfidence').textContent=`Confiança ${best.confidence}%`;$('#bestWhen').textContent=`${best.date} · ${best.window}`;$('#bestReason').textContent=best.summary;$('#openBestReason').onclick=()=>openReason(best);$('#topOpportunities').innerHTML=all.slice(0,8).map((x,i)=>`<div class="opp"><div><strong>${i+1}. ${esc(APP.forecast.beaches[x.beach_id].name)} · ${esc(x.period)}</strong><div class="muted">${esc(x.date)} · confiança ${x.confidence}%</div></div><button class="score-btn opp-open" data-key="${x.date}|${x.beach_id}|${x.period}|${x.species}"><strong>${x.score.toFixed(1)}</strong><small>ver porquê</small></button></div>`).join('');$$('.opp-open').forEach(b=>b.onclick=()=>{const [d,bid,p,s]=b.dataset.key.split('|');openReason(evaluation(d,bid,p,s))});renderStats()}
function shortTide(v){return String(v||'—').replace(' variável','').replace('perto de ','')}
function conditionLines(e){const c=e.conditions||{};return [`Mar ${Number(c.wave_offshore_m??0).toFixed(1)} m ${esc(c.wave_direction||'')} · ${Number(c.wave_period_s??0).toFixed(0)} s`,`Vento ${esc(c.wind_direction||'—')} ${Math.round(Number(c.wind_kmh)||0)} km/h`,`Maré ${esc(shortTide(c.tide_phase))} · Água ${Number(c.water_temp_c??0).toFixed(1)} °C`,`72h ${esc(c.sea_history_72h||'—')} · C${Math.round(Number(e.confidence)||0)}%`]}
